import data from "../data/aan-sources.json";
import { aanId, isReleased } from "./releases";

// Generated by aan-studio/renders/sources_export.py in rn-content-second-brain; do not edit by hand.
export type SourceLink = { label: string; url: string };
export type ImageCredit = { where: string; what: string; credit: string; url: string; card: boolean };
export type Origin = { kind: "article" | "listing" | "main"; label: string; url: string } | null;
export type SourcePost = {
  slug: string; date: string; id: string; title: string; series: string; origin: Origin;
  research: SourceLink[]; other: SourceLink[]; images: ImageCredit[];
};

export const sourcePosts: SourcePost[] = (data.posts as SourcePost[]).slice().sort((a, b) => a.date.localeCompare(b.date));

export function sourcePost(slug: string) {
  return sourcePosts.find((p) => p.slug === slug);
}

// Posts go live at 12:00 Hawaii time. A page exists and is listed from the piece's release in data/releases.json
// (lib/releases.ts); before that its address returns 404.
export function postedSoFar(now = new Date()) {
  return sourcePosts.filter((p) => isReleased(aanId(p.slug), now));
}

export function releasedSourcePost(slug: string, now = new Date()) {
  const p = sourcePost(slug);
  return p && isReleased(aanId(slug), now) ? p : undefined;
}

export function longDate(date: string) {
  return new Date(`${date}T12:00:00Z`).toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric", timeZone: "UTC" });
}

export function host(url: string) {
  try { return new URL(url).hostname.replace(/^www\./, ""); } catch { return ""; }
}
